const CANONICAL_POST_DISCOVERY_GENERAL_INFORMATION_RESPONSE = "Claro 😊 Dietavity es un programa personalizado de 28 días que te dice qué comer cada día. Cuesta $149 MXN en un solo pago e incluye desayuno, comida, cena y snack, además de apoyo por WhatsApp cuando lo necesites.\n\n¿Quieres que te muestre un ejemplo de cómo sería un día de comidas?";
function currentConversationalTask(message, interpretation = {}) {
  const task = interpretation.current_task;
  if (interpretation.interpretation_valid === false || !task ||
      !['draft', 'transform', 'summarize', 'show'].includes(task.operation) ||
      typeof task.request !== 'string' || task.request.trim().length < 5 ||
      !String(message || '').includes(task.request.trim())) return null;
  return {operation: task.operation, request: task.request.trim()};
}

function taskProductMessage(message, task) {
  if (!task) return String(message || '');
  const remainder = String(message || '').replace(task.request, '');
  // A related how-to/formatting question is part of the current task, not an
  // unknown service capability merely because it has no canonical topic.
  // Retain independently recognizable facts AND unknown provider capabilities.
  return currentQuestionClauses(remainder).filter(clause =>
    explicitProductQuestions(clause + '?').length > 0 ||
    /\b(?:dietavity|servicio|ustedes|ofrecen|tienen|garantizan|su (?:programa|app|plan))\b/i.test(clause)
  ).map(clause => clause + '?').join(' ');
}

function explicitProductQuestions(message) {
  const text = String(message || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
  // Preview requests can be imperative and omit punctuation. Require a viewing
  // request plus a meal/day object, or an otherwise unqualified sample request.
  const sampleText = text.replace(/\bpor ejemplo\b/g, '');
  const sampleRequest = /\b(?:ver|verlo|muestra\w*|ensena\w*|ejemplo)\b/.test(sampleText) && (
    /\b(?:ejemplo|muestra)\b.{0,35}\b(?:plan|menu|dia|comidas?|alimentacion)\b|\b(?:plan|menu|dia)\b.{0,35}\b(?:ejemplo|muestra|para ver)\b|\b(?:ensena\w*|muestra\w*|ver)\b.{0,30}\b(?:como (?:seria|es|se ve) un dia|que comidas|que ponen)\b/.test(sampleText) ||
    /\b(?:ver|mostrar|ensename|muestrame)(?:me)? (?:(?:un|una|algun|alguna) )?(?:ejemplo|muestra)(?:[?.,!\s]|$)/.test(sampleText) &&
      !/\b(?:ejemplo|muestra)\s+(?:de|sobre|para)\s+(?!plan\b|menu\b|un dia\b|comidas?\b)/.test(sampleText)
  );
  const asks = sampleRequest || /[?¿]|\b(?:quisiera saber|quiero (?:saber|aclarar)|dime|explica\w*|contesta|aclarar|dudas|aceptan|(?:dan|generan|emiten) (?:factura|cfdi)|cuando (?:empiezo|comienzo)|como (?:lo )?personaliz\w*|cuanto cuesta|como funciona|que incluye|cuanto tarda|en cuantas horas|cuando|como se)\b/.test(text);
  if (!asks) return [];
  if (/^\s*¿?(?:y )?como funciona (?:eso|esto)\s*\??$/.test(text)) return []; // Referent requires conversational history.
  const patterns = {
    sample_plan: sampleRequest ? /\b(?:ejemplo|muestra|menu|dia|comidas)\b/ : /(?!)/,
    invoice: /\b(?:factura\w*|cfdi)\b/,
    guarantee: /\b(?:garantia|garantizan|garantizado\w*)\b/,
    business_location: /\b(?:presencial|fisicamente|en linea|online|digital|consultorio|sucursal|oficinas?|ubicad\w*|donde estan|ir a (?:un|una|sus?)|atencion fisica)\b/,
    credentials: /\b(?:nutriolog\w*|nutricionist\w*|humano|persona o ia|persona real|inteligencia artificial|ia|quien (?:me |lo |nos )?(?:crea|hace|arma|disena|elabora|prepara)|credenciales|certificacion)\b/,
    personalization: /\b(?:personaliz\w*|alergias|preferencias|restricciones|alimentos (?:que evito|a evitar)|gustos|(?:adaptan|ajustan).{0,30}(?:lo que|alimentos)|(?:no puedo|evito) comer)\b/,
    glp1_suitability: /\b(?:plan|programa|comidas|dietavity)\b.{0,100}\b(?:glp[ \u2010-\u2015-]?1|semaglutida|ozempic)\b/,
    portal: /\b(?:accedo|acceder|entro|entrar|acceso|consulto|veo|consultar)\b.{0,35}\bportal\b/,
    medication_scope: /\b(?:incluye[n]?|venden|dan|recetan|necesito|requiere[n]?).{0,25}(?:medicamento|glp[ -]?1|ozempic|semaglutida)\b/,
    trial_promotion: /\b(?:prueba|probarlo|probar|promocion\w*|descuento\w*|gratis|gratuita|cupon\w*)\b/,
    fulfillment_timing: /\b(?:cuanto (?:tiempo )?(?:suelen? )?(?:tardar|demorar|tardan?|demoran?)|en cuant[oa]s? (?:horas|dias)|cuando (?:va a estar|estara|esta|queda|quedara|puedo verlo|puedo ver|puedo acceder|podre acceder|aparece|se genera|se entrega|recibo))\b/,
    fulfillment_notification: /\b(?:me (?:avisan|avisaran|avisas|avisa|avise|notifican|notificaran)|me llega (?:algun |un )?aviso|como se)\b.{0,70}\b(?:listo|disponible|generad[oa]|quedo|portal)\b/,
    payment_methods: /\b(?:metodos? de pago|formas? de pago|como (?:puedo )?pagar|(?:puedo |se puede )?pagar con|aceptan|tarjeta\w*|oxxo|apple pay|paypal|transferencia)\b/,
    refund: /\b(?:reembolso\w*|devolucion\w*|devuelven|devolver.*dinero|regresan.*dinero)\b/,
    WhatsApp_assistance: /\b(?:whatsapp|apoyo|soporte|ayuda (?:durante|por)|recetas a demanda)\b/,
    support_limits: /\b(?:limite|limites|maximo)\b.{0,45}\b(?:mensajes|consultas)\b|\blimite\b.{0,60}\bwhatsapp\b/,
    support_timing: /\b(?:tiempo (?:estimado )?de respuesta|cuanto (?:tardan|demoran) en (?:contestar|responder)|respond(?:e|en|er) (?:rapido|en)|24\s*\/\s*7|horario de (?:atencion|soporte))\b/,
    price: /\b(?:cuanto cuesta|cuanto (?:vale|cobran)|precio|costo|coste)\b/,
    billing: /\b(?:suscripcion|mensualidad|renueva|renovacion|recurrente|cada mes|por mes|paga[rs]? una vez|pago unico|un solo pago)\b/,
    prepared_food: /\b(?:comidas? preparadas?|comidas? listas?|platos listos|(?:mandan|entregan|envian|llevan|traen).{0,35}(?:comida|platillos|platos)|a domicilio|(?:comidas?|platillos) a casa)\b/,
    what_is_included: /\b(?:que incluye|que recibo|que viene incluido|inclusiones|cuantas comidas)\b/,
    how_it_works: /\b(?:como funciona|como (?:se usa|uso el)|en que (?:se basan?|consiste)|como arman)\b/,
    start_date: /\b(?:cuando (?:puedo )?(?:empezar|comenzar|empiezo|comienzo)|fecha de inicio|elegir (?:el inicio|cuando empezar))\b/,
    after_payment: /\b(?:despues de (?:pagar|la compra|comprar|completar el pago)|tras (?:pagar|el pago)|que (?:pasa|sigue) (?:al|cuando) (?:pago|pagar))\b/,
    post_purchase: /\b(?:despues de (?:los )?28 dias|al (?:terminar|acabar) (?:el programa|los 28 dias))\b/,
    testimonials: /\b(?:testimonios|resenas|casos de exito|opiniones de clientes)\b/,
    international_pricing: /\b(?:dolares|usd|euros|extranjero|otro pais|fuera de mexico|precio internacional)\b/,
    setup_data: /\b(?:datos medicos|formulario|setup)\b/,
    shopping_list: /\blistas? (?:de (?:compras?|super)|semanal(?:es)?)\b/,
    support_contact: /\b(?:contacto|email|correo|telefono|con quien hablo)\b/,
    privacy: /\b(?:privacidad|datos personales|datos sensibles|protegen (?:mi|la) informacion)\b/,
  };
  const durationClauses = text.split(/[?;\n]/).filter(clause => patterns.fulfillment_timing.test(clause));
  if (!durationClauses.some(clause =>
    /\b(?:plan|programa|portal|generar\w*|pagar|pago|personalizacion|listo|disponible|acceder)\b/.test(clause) ||
    /^\s*¿?(?:despues de pagar )?(?:cuanto (?:tiempo )?(?:suelen? )?(?:tardar|demorar|tardan?|demoran?)|en cuantas horas (?:esta|queda) listo|cuando estara disponible)\s*$/.test(clause))) patterns.fulfillment_timing = /(?!)/;
  const topics = Object.entries(patterns).map(([topic, re]) => ({topic, index: text.search(re)}))
    .filter(match => match.index >= 0).sort((a, b) => a.index - b.index).map(match => match.topic);
  const unconfirmedQuestion = text.split(/[?;\n]/).some(clause =>
    /¿\s*(?:tienen|ofrecen|hacen|hay|puedo|la app|su app|el programa)/.test(clause) &&
    !Object.values(patterns).some(re => re.test(clause)));
  if (topics.includes('fulfillment_timing')) {
    const index = topics.indexOf('after_payment');
    if (index >= 0) topics.splice(index, 1);
  }
  if (unconfirmedQuestion) topics.push('unconfirmed_detail');
  return topics;
}

function uncertaintySubject(subject) {
  return String(subject).replace(/https?:\/\/\S+|www\.\S+|\b[0-9a-f]{8}-(?:[0-9a-f]{4}-){3}[0-9a-f]{12}\b|\b\w*(?:__harness|offer_context|buyer_signal|checkout_authorized|glp1_validation)\w*\b|28d-149-v1/gi,'[dato omitido]')
    .replace(/[«»<>`*_{}\[\]¿?]/g,'').slice(0,500);
}

function currentQuestionUnits(message) {
  const text = String(message || '').slice(0, 4000);
  const units = [];
  for (const part of text.split(/(?<=[?])|[\n.!;]+/)) {
    const value = part.trim().replace(/^(?:y |además,? |entonces,? |si no,? )/i, '');
    if (!value || /^(?:hola|gracias|ok|perfecto|si|sí|no|como funciona eso|cómo funciona eso)$/i.test(value)) continue;
    const start = value.search(/\b(?:qu[eé]|qui[eé]n|c[oó]mo|cu[aá]nt\w*|cu[aá]l\w*|cu[aá]ndo|d[oó]nde|necesitan|requieren|incluy\w*|aceptan|ofrecen|tienen|pued\w*|dan|hay|me (?:das|dan|pasas|pasan)|dame|mu[eé]strame|confir\w*|quiero saber|quisiera saber)\b/i);
    if (start < 0 && !/[¿?]/.test(value)) continue;
    const request = value.replace(/[¿?]/g, '').trim();
    // Unqualified discovery and referential follow-ups remain contextual.
    if (/^(?:y )?(?:quiero saber m[aá]s|qu[eé] ofrecen|qu[eé] es dietavity|c[oó]mo funciona (?:eso|esto)|me das informaci[oó]n)$/i.test(request)) continue;
    if (/^(?:si|sí|ok|okay|perfecto|vale|listo|gracias|no|como|cómo|y)$/i.test(request)) continue;
    units.push(request);
  }
  return [...new Set(units)];
}

function currentQuestionClauses(message) {
  return currentQuestionUnits(message).flatMap(unit => unit.split(/\s+(?:y|adem[aá]s|tambi[eé]n)\s+(?=(?:(?:yo|me|ustedes)\s+)?(?:pued\w*|debo|deber[ií]a|quier\w*|necesit\w*|hay|tienen|ofrecen|incluy\w*|aceptan|das|dan|dame|mu[eé]strame|cu[aá]nt\w*|c[oó]mo|qu[eé]\s|qui[eé]n|confir\w*))/i))
    .map(clause => clause.trim()).filter(Boolean);
}

function constrainedSampleRequest(subject) {
  const text = String(subject).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
  return /\b(?:vegetarian\w*|vegan\w*|gluten|intoleran\w*|alerg\w*|celiac\w*|sin (?!pagar|comprar|datos|pedir)\w+|segun mi|para mi (?:alergia|condicion|tratamiento))\b/.test(text);
}

function practicalGuidanceQuestion(subject) {
  const text = String(subject || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
  if (!text) return false;
  const providerOrCapability = /\b(?:dietavity|programa|plan|servicio|soporte|app|portal|ustedes|incluye|ofrece|ofrecen|tienen|garantiza\w*|adapta\w*|confirma\w*|pueden)\b/;
  if (providerOrCapability.test(text)) return false;
  const foodObject = /\b(?:comidas?|recetas?|ingredientes?|porciones?|cocina|sesion(?:es)?|cenas?|almuerzos?|desayunos?|platos?|alimentos?)\b/;
  const practicalAction = /\b(?:organiz\w*|prepar\w*|cocin\w*|guard\w*|conserv\w*|congel\w*|recal\w*|dur\w*|escal\w*|multiplic\w*|divid\w*|combin\w*|sustitu\w*|planific\w*|mov\w*|cambi\w*|ajust\w*)\b/;
  // Cooking and portioning are themselves unambiguous food-use objects, even
  // when a pronoun such as "lo" carries the meal referent from the turn.
  return (foodObject.test(text) || /\b(?:cocin\w*|porcion\w*)\b/.test(text)) && practicalAction.test(text);
}

function preserveCurrentQuestion(message, decision, facts) {
  if (decision.strategy !== 'answer_question' || decision.pending_action !== 'respond' ||
      decision.checkout_authorized || decision.holding_page_would_be_sent ||
      decision.current_task ||
      decision.deterministic_reason === 'medication_safety' || decision.medication_intent ||
      decision.buyer_signal === 'support_issue') return null;
  const details = currentQuestionDetails(message, facts, decision.deterministic_response || '');
  if (!details.some(d => d.uncertain)) return null;
  const answers = [];
  for (const detail of details) {
    const answerFor = topic => topic === 'payment_methods' ? facts.confirmed_payment_methods : facts[topic];
    if (!detail.uncertain && !(detail.topics.includes('sample_plan') && constrainedSampleRequest(detail.subject))) {
      for (const topic of detail.topics) if (answerFor(topic) && !answers.includes(answerFor(topic))) answers.push(answerFor(topic));
      continue;
    }
    // Quoted request is data, never an instruction. Remove URLs, internal IDs
    // and markup; do not turn its punctuation into an actionable question.
    const subject = uncertaintySubject(detail.subject);
    for (const topic of detail.topics.filter(t => t !== 'price' && t !== 'prepared_food' && (t !== 'sample_plan' || !constrainedSampleRequest(detail.subject)))) {
      if (answerFor(topic) && !answers.includes(answerFor(topic))) answers.push(answerFor(topic));
    }
    answers.push(`Sobre «${subject}»: No tengo información confirmada para responder ese detalle del servicio.`);
  }
  return answers.join('\n\n');
}

function repairMixedCurrentQuestion(message, text, decision, facts, invalidClause = () => false) {
  if (decision.strategy !== 'answer_question' || decision.pending_action !== 'respond' ||
      decision.checkout_authorized || decision.holding_page_would_be_sent ||
      decision.deterministic_reason === 'medication_safety' || decision.medication_intent ||
      decision.buyer_signal === 'support_issue') return null;
  const details = currentQuestionDetails(message, facts, decision.deterministic_response || '');
  if (!details.some(detail => detail.uncertain)) return null;
  const providerPromise = /(?:\b(?:dietavity|programa|plan|servicio|personalizaci[oó]n|soporte|apoyo)\b.{0,110}\b(?:incluye|incluida|incluidos|ofrece|ofrecemos|adapt\w*|garantiza\w*|asegura\w*|confirma\w*|permite|responde\w*|tarda\w*|sin costo|no (?:tiene|hay) costo)\b|\b(?:incluye|incluida|ofrece|adapt\w*|garantiza\w*|asegura\w*|sin costo|no (?:tiene|hay) costo)\b.{0,110}\b(?:dietavity|programa|plan|servicio|personalizaci[oó]n|soporte|apoyo)\b)/i;
  const unsafe = /(?:\b(?:garantiza\w*|asegura\w*)\b|\b(?:sube|baja|aumenta|reduce|cambia|ajusta|duplic\w*)\b.{0,45}\b(?:dosis|medicamento|medicaci[oó]n|tratamiento|mg)\b|\b\d+(?:[.,]\d+)?\s*mg\b|MARCADOR_NO_SOPORTADO|\b(?:offer_context|glp1_validation|checkout_authorized)\b)/i;
  // These are capability/SLA assertions even when the draft omits the product
  // name. They are not practical food-use guidance and must not survive merely
  // because another clause is useful.
  const unsupportedCapability = /(?:\b(?:sincroniz\w*|integraci[oó]n|exportaci[oó]n|csv|xml|videollamada\w*|consulta privada)\b|\b(?:te )?avis(?:amos|aremos)\b.{0,45}\b(?:autom[aá]tic\w*|listo|disponible)\b|\b(?:estar[aá]|queda)\b.{0,35}\b(?:en unas horas|mismo d[ií]a|en breve|poco despu[eé]s)\b|\b(?:en unas horas|mismo d[ií]a|en breve|poco despu[eé]s)\b|\b(?:responde(?:mos)?|contest(?:amos|aremos))\b.{0,35}\b(?:minutos?|horas?)\b|(?:ajustamos|calculamos|prescribimos).{0,35}(?:calor[ií]as|porciones|macros|macronutrientes)\b)/i;
  const unknownQualifiedPrice = details.some(detail => detail.uncertain && /\b(?:consulta privada|pdf|imprim\w*|exportaci[oó]n|csv|xml)\b/i.test(detail.subject));
  const units = String(text || '').match(/[\s\S]+?(?:[.!?](?=\s|$)|\n|$)/g) || [];
  const kept = units.filter(unit => unit.trim() && !invalidClause(unit) && !unsafe.test(unit) && !providerPromise.test(unit) &&
    !unsupportedCapability.test(unit) && !(unknownQualifiedPrice && /\$\s*\d+|\b\d+\s*mxn\b/i.test(unit)));
  // A fully unsafe draft must still take the established safe fallback path.
  if (!kept.length) return preserveCurrentQuestion(message, decision, facts);
  const practicalDraft = /\b(?:guarda|recalienta|cocina|prepara|organiza|conserva|congela|divide|multiplica)\w*/i.test(kept.join(' '));
  const explicitBasePrice = /(?:\$\s*149\b|\b149\s*mxn\b)/i.test(String(message));
  const independentKnownTopics = explicitProductQuestions(message).filter(topic =>
    topic !== 'unconfirmed_detail' && !['support_timing', 'support_limits', 'fulfillment_timing', 'fulfillment_notification'].includes(topic));
  // A pure unknown-service answer still uses the mature bounded fallback. The
  // exception is a genuinely mixed food-use answer or an explicit known base
  // price paired with an unknown inclusion/capability.
  if (details.every(detail => detail.uncertain) && !practicalDraft && !explicitBasePrice && independentKnownTopics.length < 2) return preserveCurrentQuestion(message, decision, facts);
  let output = kept.join('').trim();
  const answerFor = topic => topic === 'payment_methods' ? facts.confirmed_payment_methods : facts[topic];
  const appended = [];
  for (const detail of details) {
    if (!detail.uncertain) {
      for (const topic of detail.topics) {
        const answer = answerFor(topic);
        if (answer && !productAnswerCoverage([topic], output).covered_topics.includes(topic) && !appended.includes(answer)) appended.push(answer);
      }
    }
    if (detail.uncertain) {
      const uncertainty = `Sobre «${uncertaintySubject(detail.subject)}»: No tengo información confirmada para responder ese detalle del servicio.`;
      if (!output.includes(uncertainty) && !appended.includes(uncertainty)) appended.push(uncertainty);
    }
  }
  if (appended.length) output += `${output ? '\n\n' : ''}${appended.join('\n\n')}`;
  // This early contract path normally bypasses the later question guard. Honor
  // the deterministic policy's limit without touching answer clauses or the
  // bounded-uncertainty additions above.
  const questions = output.match(/¿[^?]*\?/g) || [];
  const maxQuestions = Number.isInteger(decision.max_questions) ? decision.max_questions : 1;
  if (questions.length > maxQuestions) {
    output = output.replace(/¿[^?]*\?/g, '').replace(/\s+\n/g, '\n').trim();
    if (maxQuestions > 0) output += `\n\n${questions.slice(0, maxQuestions).join('\n')}`;
  }
  return output;
}

function canonicalClauseAnswers(message, facts) {
  const decision = {strategy:'answer_question',pending_action:'respond'};
  const preserved = preserveCurrentQuestion(message, decision, facts);
  if (preserved !== null) return preserved;
  const topics = [...new Set(currentQuestionClauses(message).flatMap(clause => explicitProductQuestions(clause + '?')))];
  return topics.map(topic => topic === 'payment_methods' ? facts.confirmed_payment_methods : facts[topic]).filter(Boolean).join('\n\n');
}

function currentQuestionDetails(message, facts, confirmedResponse = '') {
  // Grammatical words and request verbs convey speech acts, not product facts.
  const grammar = new Set(`
    informacion menus a al algo algun alguna algunos algunas ante antes con contra cual cuales cuando cuanto cuanta cuantos cuantas
    como de del desde donde puedes contamos veo ver cobrar mes mensual paga despues contar mas el ella
    ellos en entre es esa esas ese eso esos esta estas este esto estos exactamente forma hay la
    las le les lo los me mi mis muy no nos o para por porque que quien quienes
    se si sin sobre su sus te tienen tiene tener tu tus un una unos unas ustedes y
    ya yo usted puedo puede pueden podria podrian quiero quisiera saber dime dame dar da dan das mostrar
    muestra muestrame mostrarme verlo ejemplo ejemplos incluye incluyen incluyes incluido incluida recibo recibir necesito necesitan requiere requieren ser
    seria son sera hacer hace hacen haceis funciona funcionan funcionar confirmar confirman confirmen confirmenme confirma confirmacion realmente real
    favor gracias ahora entonces ademas tambien solo solamente durante inicio empezar comenzar estar estara quede quedo queda entrega
    aparece llega suele suelen alimentacion personalmente ir verlos toman consideran respetan base basa basan ensenas ensena ensename ensenar
    buenas tardes hola buenos noches cuentame explicame trata interesa conocer dieta metodo depende edad cobro cobra cobran otra
    cada sigo duda sucede detalladamente detalles mandame mandas enviame enlace link comprarlo contratarlo pero muestras completa completo todo
    toda todos todas normalmente pasa tengo avise avisaran dias manana respecto acerca costo cuesta cuestan precio pago pagar
    plan programa dietavity servicio comidas comida menu dia
  `.trim().split(/\s+/));
  const normalize = value => String(value).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
  const terms = value => (normalize(value).match(/[a-z0-9]+/g) || []).filter(t => t.length > 2 && !grammar.has(t));
  const stem = t => t.length > 5 ? t.slice(0,5) : t;
  return currentQuestionClauses(message).map(subject => {
    const topics = explicitProductQuestions(subject + '?').filter(t => t !== 'unconfirmed_detail');
    const confirmed = topics.map(t => facts[t] || '').join(' ') + ' ' + confirmedResponse;
    const vocabulary = new Set(terms(confirmed).map(stem));
    const topicAliases = new Set([
      ...(topics.some(t => ['glp1_suitability','medication_scope'].includes(t)) ? ['glp1','estoy','usando','usan','uso','pensado','pensada','personas','adultos'] : []),
      ...(topics.includes('support_timing') ? ['rapido','rapidez','responder','correo'] : []),
    ]);
    const missing = terms(subject.replace(/\bentregas? en\s+[\p{L}]+$/iu, 'entrega').replace(/\bd[oó]nde entregan$/iu, 'entrega')).filter(t => !topicAliases.has(t) && !vocabulary.has(stem(t)) && !explicitProductQuestions(t + '?').some(topic => topics.includes(topic)));
    // Canonical aliases name the same fact, not an additional requested feature.
    const aliases = /^(?:funcion\w*|arma\w*|crea\w*|elabor\w*|disena\w*|tard\w*|demor\w*|atiend\w*|lleven|gener\w*|entrega\w*|manda\w*|paga\w*|empiezo|comienzo|domicilio|cierto|listo|lista|listos|listas|personaliz\w*|informacion|factura|cfdi|acepta\w*|ubicad\w*|estan|digital|presencial|linea|metodo\w*|forma\w*|pago\w*|tarjeta\w*|transferencia|suscripcion|mensualidad|renovacion|recurrente\w*|unico|vez|inclu\w*|nutriolog\w*|crea|hace|garantia|garantizan|garantizado|gratis|gratuita|prueba|promocion|descuento|reembolso|avisan|notifican|aviso|horas|hora|dias|tiempo|estimado|limite|limites|maximo|consultas|mensajes|respuesta|atencion|soporte|comprar|compra)$/;
    const practical = practicalGuidanceQuestion(subject);
    return {subject, topics, practical,
      uncertain: !practical && ((!topics.length && !confirmedResponse && terms(subject).length > 0) || missing.some(t => !aliases.test(t)))};
  });
}

function hasExplicitCurrentReminderRequest(message) {
  const text = String(message || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
  if (/\bno\s+(?:(?:me|quiero|necesito|que)\s+)*(?:recuerd\w*|record\w*|avis\w*)/.test(text)) return false;
  return /\b(?:recuerdame|recordarme|me (?:puedes |podrias |podrian |pueden )?recordar)\b/.test(text) ||
    /\b(?:avisame|me (?:puedes |podrias )?avisar)\b.{0,45}\b(?:manana|pasado manana|lunes|martes|miercoles|jueves|viernes|sabado|domingo|en \w+ (?:dias|semanas)|el \d+)\b/.test(text) &&
    !/\b(?:listo|disponible|generad[oa])\b/.test(text);
}

function glp1PurchaseHoldingResponse(offerContext) {
  if (offerContext !== 'glp1_validation') return {};
  return {
    pending_action: 'respond',
    checkout_authorized: false,
    checkout_authorization_type: null,
    holding_page_would_be_sent: true,
    holding_page_url: 'https://dietavity.com/programa-glp1',
    deterministic_response: 'Claro 😊 Te comparto el siguiente paso:\nhttps://dietavity.com/programa-glp1',
  };
}

function detectOfferContext(message) {
  return String(message ?? '').normalize('NFC').trim().replace(/\s+/gu, ' ').toLocaleLowerCase('es') ===
    '¡hola! quiero saber más.' ? 'glp1_validation' : null;
}

function medicationIntent(message) {
  const text = normalizeMessage(message);
  if (/\b(grave|graves|intenso|intensa|no puedo respirar|desmayo|desmayando|empeora|empeorando|no puedo retener liquidos)\b/.test(text)) return 'urgent';
  if (/\b(dosis|dosificar|inyect\w*|eficacia|efectos? secundarios?|vomit\w*|nauseas|suspender\w*|suspendo|tratamiento)\b/.test(text) ||
      /\b(cuanto (?:glp[ -]?1 )?(?:debo|deberia|puedo) usar|cada cuanto|me (?:lo )?pongo|puedo usarlo(?=$| si .{0,45}(?:medicamento|tratamiento))|(?:puedo|debo|deberia) (?:dejar|cambiar|empezar) (?:el |la |mi |de |a )?(?:medicamento|medicacion|tratamiento|ozempic|wegovy|semaglutida|glp[ -]?1|tomar(?:lo)?|usar(?:lo)?)|(?:dejar|empezar) (?:de |a )?(?:usar|tomar)|(?:recomiendas?|recomiendan) empezar|que medicamento .*recomiend)\b/.test(text)) return 'management';
  if (/\b(?:medicamento|medicacion|ozempic|wegovy|semaglutida|glp[ -]?1)\b/.test(text) &&
      /\b(?:puedo|debo|deberia) (?:dejar|cambiar|empezar)\b/.test(text)) return 'management';
  // An unqualified treatment-action question remains conservative; cooking
  // objects such as 'dejar todo listo' do not match this boundary.
  if (/\b(?:puedo|debo|deberia) (?:dejar|cambiar|empezar)(?:lo|la)?$/.test(text)) return 'management';
  const medication = '(?:(?:el|los|las|un|una) )?(?:medicamentos?(?: glp[ -]?1)?|medicacion|glp[ -]?1|ozempic|wegovy|semaglutida|inyecciones)';
  const provider = '(?:(?:ustedes|dietavity) )?';
  const scope = new RegExp('^(?:hola )?' + provider + '(?:(?:me )?(?:dan|venden|entregan|recetan|mandan|envian|proporcionan|proporciona|vende|entrega|receta) ' + medication + '|(?:el programa |su programa |el precio )?(?:incluye|incluyen|es con|requiere|requieren) ' + medication + '|(?:necesito|hay que tomar|tengo que tomar) ' + medication + '|' + medication + ' (?:viene incluido|vienen incluidas|esta incluido|estan incluidas))$');
  if (scope.test(text)) return 'product_scope';
  const preference = new RegExp('^(?:(?:no |claro )*)(?:(?:me interesa|quiero)(?: algo)?(?: con| tomar)? ' + medication + '|(?:busco|prefiero|quiero) algo (?:sin ' + medication + '|que no incluya ' + medication + ')|quiero tomar nada)$');
  // Require rejection for the first construction; positive treatment interest is
  // not a product preference merely because a medicine is named.
  if (preference.test(text) && (/^(?:no )+/.test(text) || /\b(?:sin|que no incluya)\b/.test(text))) return 'preference';
  return null;
}

function glp1SafetyResponse(message, topic) {
  const intent = medicationIntent(message);
  if (intent === 'urgent') return 'Si tienes síntomas graves o que empeoran rápidamente, busca atención médica de inmediato. Dietavity no puede diagnosticar ni tratar estos síntomas.';
  if (intent === 'product_scope' || intent === 'preference') return null;
  if (intent === 'management' || topic === 'health_scope') {
    return 'Eso puede depender de tu tratamiento y no sería seguro que Dietavity te indicara cambios en tu medicamento. Lo adecuado es consultarlo con el profesional que te lo prescribió.';
  }
  return null;
}

function glp1ProductScopeResponse(message) {
  if (medicationIntent(message) !== 'product_scope') return null;
  return 'No. Dietavity no vende, entrega ni receta medicamentos GLP-1. Somos un programa de alimentación personalizado de 28 días que te ayuda a organizar qué comer cada día. ¿Qué te gustaría saber sobre el programa?';
}

function normalizeMessage(value) {
  return String(value || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLocaleLowerCase('es-MX')
    .replace(/[¡!¿?.,;:]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function isStrongAffirmation(message) {
  return /^(si|sip|si quiero|claro|por favor|adelante)$/.test(normalizeMessage(message));
}

function isWeakAcknowledgement(message) {
  return /^(ok|okay|perfecto|vale|listo)$/.test(normalizeMessage(message));
}

function hasDeterministicBroadInformationRequest(message, session = {}) {
  const value = normalizeMessage(message);
  const explicitRequest = /^(?:realmente\s+)?todo\s+por favor$/.test(value) ||
    /^(?:realmente\s+todo|quiero\s+(?:saber|conocer)\s+todo|(?:cuentame|explicame|dime)\s+todo|me\s+interesa\s+saber\s+todo|quiero\s+mas\s+informacion|mas\s+informacion|cuentame\s+mas)$/.test(value);
  if (explicitRequest) return true;

  // A bare "todo" only means "tell me broadly" when it answers a question that
  // invited discovery or more product detail. In purchase context it stays
  // ambiguous and can never become Checkout authorization.
  return value === 'todo' &&
    ['primary_goal', 'show_example', 'explain_offer'].includes(session.last_question_type);
}

function hasExplicitComprehensiveInformationRequest(message) {
  const value = normalizeMessage(message);
  return /^(?:realmente\s+)?todo(?:\s+por favor)?$/.test(value) ||
    /\b(?:explicame|cuentame|dime|dame|quiero|quisiera)\b.{0,45}\b(?:todo|toda la informacion|bien como funciona|todo lo que incluye)\b/.test(value) ||
    /\b(?:todo|toda la informacion|todo lo que incluye)\b.{0,45}\b(?:programa|dietavity|incluye|funciona)\b/.test(value);
}

function hasDeterministicExplicitPurchase(message, session = {}, now = new Date()) {
  const value = normalizeMessage(message);
  // Negated, conditional and explicitly unresolved requests are not authorization.
  if (/\b(?:no (?:lo quiero|lo pago|quiero|deseo|voy a|me mandes|me envies)|si (?:me |nos )?(?:aceptan|tienen|hay|dan|generan|funciona|sirve|me sirve|se puede)|solo si|siempre que|no (?:ahora|todavia|aun)|todavia no|aun no|pero primero|antes de (?:comprar|pagar))\b/.test(value)) return false;
  const contextualObject = session.last_question_type === 'purchase_confirmation' &&
    validContext(session, now) &&
    /^(?:si[, ]+)?(?:mandalo|envialo|pasalo|compartelo)(?: porfa| por favor)?(?:$|[.,;? ]+(?:que|como|cuando|generan|dan|aceptan))/.test(value);
  return contextualObject || (
    /^(?:(?:si|va|bueno|bien|de acuerdo) )?lo (?:pago|quiero)(?:$| (?:porfa|por favor|ahora|pero|y|que|como|cuando|dan|generan|aceptan)\b)/.test(value) ||
    /\b(quiero|deseo|voy a)\s+(comprar(?:lo|la)?|adquirir(?:lo|la)?|pagar(?:lo|la)?)\b/.test(value) ||
    /\b(quiero|deseo)\s+(empezar|comenzar)\b/.test(value) ||
    /\b(mandame|enviame|pasame|comparteme)\b.*\b(enlace|link)\b/.test(value) ||
    /\b(?:me\s+)?(?:mandas|envias|pasas|compartes)\b.*\b(enlace|link)\b/.test(value) ||
    /\b(enlace|link)\b.*\b(pagar|pago|comprar|adquirir)\b/.test(value) ||
    /\bdonde\s+(pago|puedo pagar|lo compro)\b/.test(value) ||
    /^(?:como pago|como puedo pagar)(?: por favor)?$/.test(value) ||
    /^(?:si )?(?:quiero|deseo) contratar(?:lo|la| el (?:programa|plan))?(?: por favor)?$/.test(value)
  );
}

function hasDeterministicAiValueObjection(message) {
  const value = normalizeMessage(message);
  const aiAlternative = /\b(ia|inteligencia artificial|chat\s*gpt|chatgpt|gemini|claude|copilot|chatbot|bot|asistente virtual|maquina)\b/;
  const humanPreference = /\b(no quiero (?:hablar|tratar) con (?:una )?(?:maquina|ia|bot)|prefiero (?:hablar|tratar) con (?:una )?(?:persona|humano|nutriologo)|(?:quiero|puedo) (?:hablar|tratar) con (?:una )?(?:persona|humano|nutriologo)|(?:atienda|atencion) (?:una )?(?:persona|humano))\b/;
  if (!aiAlternative.test(value) || humanPreference.test(value)) return false;

  return (
    /\b(mejor|para eso)\b.{0,45}\b(uso|utilizo|pregunto|consulto|pido)\b/.test(value) ||
    /\b(lo|eso)\s+(?:lo\s+)?puedo\s+(hacer|pedir|conseguir|obtener)\b/.test(value) ||
    /\bpuedo\s+(pedirle|preguntarle|consultarle)\s+(?:eso|lo mismo)\b/.test(value) ||
    /\bpor que\s+(?:deberia\s+)?pagaria\b/.test(value) ||
    /\bque diferencia (?:hay|tiene|habria)\b.{0,55}\b(usar|preguntar(?:le)?|consultar(?:le)?|pedir(?:le)?)\b/.test(value) ||
    /\bpor que no (?:hacerlo|pedirlo|preguntarlo|consultarlo)\b.{0,35}\b(directamente|gratis|por mi cuenta|yo mismo|yo misma)\b/.test(value) ||
    /\b(?:gratis|sin pagar|por mi cuenta)\b.{0,35}\b(ia|chat\s*gpt|chatgpt|chatbot|asistente virtual)\b/.test(value)
  );
}

function hasDeterministicMaterialQuestion(message) {
  const value = normalizeMessage(message);
  if (/\b(?:no (?:tengo|uso|manejo) tarjetas?|sin tarjeta|pagar sin tarjeta)\b/.test(value)) return true;
  if (/\b(?:platicas?|charlas?|consultas? por videollamada|videollamadas?|me llama un nutriologo|llamada con (?:un )?nutriologo)\b/.test(value)) return true;
  const questionLike = /[?¿]/.test(String(message || '')) ||
    /\b(aceptan|cuanto|como|cuando|cual|metodos?|formas?|reembolso|devolucion|seguro|privacidad|alerg|condicion|incluye)\b/.test(value);
  if (!questionLike) return false;
  return /\b(oxxo|apple pay|tarjeta|paypal|mercado pago|metodos?|formas?|precio|cuesta|inicio|empezar|reembolso|devolucion|salud|alerg|condicion|privacidad|seguro|incluye|personaliza)\b/.test(value);
}

function asksBusinessLocation(message) {
  const value = normalizeMessage(message);
  return /\bdonde (?:estan|se encuentran|se ubican)(?: ubicados)?(?: ustedes| dietavity)?(?:$| y\b)/.test(value) ||
    /\b(?:tienen|hay|cuentan con|donde tienen)\b.{0,25}\b(?:consultorio|sucursal|oficinas?|sede)\b/.test(value) ||
    /\b(?:es|son|servicio|atienden|atencion|consulta|programa)\b.{0,25}\b(?:presencial|fisicamente|en persona|en linea|online|digital)\b/.test(value) ||
    /\b(?:todo|funciona) (?:es )?en linea\b/.test(value);
}

function asksPost28DayContinuation(message) {
  const value = normalizeMessage(message);
  const afterPeriod = /\b(?:despues|al terminar|cuando (?:termine|acabe)|una vez (?:terminen|acabados)|pasados)\b.{0,45}\b(?:28 dias|programa|plan)\b/.test(value) ||
    /\b(?:28 dias|programa|plan)\b.{0,45}\b(?:despues|al terminar|termine|termina|acabe|continua|seguir|otro programa|que pasa|cuanto (?:pago|se paga|costaria))\b/.test(value);
  return afterPeriod;
}

function asksPreparedFoodDelivery(message) {
  const value = normalizeMessage(message);
  return /\b(?:hacen|tienen|hay)\s+entregas?\b/.test(value) ||
    /\b(?:donde|a donde|en que lugares?)\s+entregan\b/.test(value) ||
    /\bentregan\b.{0,28}\b(?:cdmx|domicilio|casa|comida|alimentos?|platillos?|menus?)\b/.test(value) ||
    /\b(?:me|nos)\s+(?:mandan|envian|llevan|entregan)\b.{0,28}\b(?:comida|alimentos?|platillos?|menus?)\b/.test(value) ||
    /\b(?:son|mandan|envian|entregan|recibo|incluye|venden)\b.{0,25}\b(?:comidas?|alimentos?|platillos?)\s+preparad[oa]s?\b/.test(value) ||
    /\bquiero\b.{0,25}\b(?:lleven|manden|envien|entreguen)\b.{0,25}\b(?:comida|menus?|platillos?)\b/.test(value);
}

function asksBasicBilling(message) {
  const value = normalizeMessage(message);
  return /\b(?:un|solo|unico)\s+(?:solo\s+)?pago\b/.test(value) ||
    /\b(?:se cobra|cobran|pago|se paga)\b.{0,18}\b(?:cada mes|mensual(?:mente)?|automaticamente|otra vez)\b/.test(value) ||
    /\b(?:renovacion|renueva|suscripcion|mensualidad)\b/.test(value);
}

function explicitlyUnresolved(message) {
  return /\b(?:sigo con (?:la )?duda|aun tengo (?:la )?duda|todavia tengo (?:la )?duda|no me queda claro|no entendi|no entiendo|no resolvio|no responde|misma duda)\b/.test(normalizeMessage(message));
}

function repeatedBillingNeedsClarification(message, previousAssistantMessage) {
  if (asksPost28DayContinuation(message)) return false;
  const previous = normalizeMessage(previousAssistantMessage);
  const alreadyAnswered = /\b(?:un solo pago|no hay renovacion automatica|sin renovacion automatica|no se renueva automaticamente)\b/.test(previous);
  return alreadyAnswered && (asksBasicBilling(message) || explicitlyUnresolved(message));
}

function hasCheckoutAlreadySent(session = {}) {
  return Boolean(session.checkout_sent_at) || session.conversation_stage === 'checkout_pending';
}

function resolveCurrentCommercialQuestions(message, session = {}) {
  const value = normalizeMessage(message);
  const asksOneTimePayment = /\b(?:un|solo|unico)\s+(?:solo\s+)?pago\b/.test(value);
  const asksRenewal = asksOneTimePayment || /\b(?:despues me cobran|cobran otra vez|se cobra.{0,18}(?:cada mes|mensual|otra vez)|renovacion|renueva|mensualidad|suscripcion)\b/.test(value);
  const asksPrice = /\b(?:cuanto (?:cuesta|vale)|que costo|precio)\b/.test(value) || asksOneTimePayment || asksRenewal;
  const asksOxxo = /\boxxo\b/.test(value);
  const asksOxxoHow = asksOxxo && (
    /\b(?:como (?:es|funciona|pago)|donde pago|pagar|pago)\b.{0,25}\boxxo\b/.test(value) ||
    /\boxxo\b.{0,25}\b(?:como|funciona|pagar|pago)\b/.test(value)
  );
  const noCard = /\b(?:no (?:tengo|uso|manejo) tarjetas?|sin tarjeta|pagar sin tarjeta)\b/.test(value);
  const asksTalks = /\b(?:platicas?|charlas?)\b/.test(value);
  const asksVideoConsultation = /\b(?:consultas? por videollamada|videollamadas?)\b/.test(value);
  const asksNutritionistCall = /\b(?:me llama un nutriologo|llamada con (?:un )?nutriologo)\b/.test(value);
  const asksHowItWorks = /\b(?:como funciona|como es el programa)\b/.test(value);
  const asksStart = /\b(?:cuando (?:empiezo|inicio|comienza|puedo (?:empezar|comenzar))|fecha de inicio)\b/.test(value);
  const asksPortal = /\b(?:donde (?:veo|recibo|consulto)|en donde (?:veo|recibo|consulto))\b.{0,35}\b(?:programa|plan)\b/.test(value);
  const unsupportedFeature = asksTalks || asksVideoConsultation || asksNutritionistCall;
  const checkoutAlreadySent = hasCheckoutAlreadySent(session);

  const businessLocation = asksBusinessLocation(message);
  const asksPayment = businessLocation && /\b(?:pago|pagar|tarjeta|metodos? de pago)\b/.test(value);
  const parts = [];
  if (businessLocation) parts.push(BUSINESS_LOCATION_RESPONSE);
  if (asksPayment && !asksOxxo && !noCard) parts.push('Aceptamos tarjeta de crédito, tarjeta de débito, OXXO y Apple Pay.');
  if (asksPrice) {
    parts.push('El programa personalizado de Dietavity cuesta $149 MXN en un solo pago.');
  }
  if (asksRenewal) {
    parts.push('No hay mensualidad ni renovación automática.');
  }
  if (unsupportedFeature) {
    const feature = asksVideoConsultation
      ? 'consultas por videollamada'
      : asksNutritionistCall
        ? 'llamadas con un nutriólogo'
        : 'pláticas programadas';
    parts.push(`No ofrecemos ${feature}: recibes tu programa personalizado en el portal y durante los 28 días puedes pedir apoyo por WhatsApp cuando lo necesites.`);
  }
  if (asksHowItWorks) {
    parts.push('Después del pago completas tu personalización, preparamos tu programa de 28 días y lo consultas en el portal Dietavity.');
  }
  if (asksStart) {
    parts.push('Puedes elegir comenzar desde hoy hasta 30 días calendario después de la compra.');
  }
  if (asksPortal) {
    parts.push('El programa se consulta en el portal Dietavity después del pago verificado y de completar tu personalización.');
  }
  if (noCard || asksOxxoHow) {
    const checkoutReference = checkoutAlreadySent
      ? 'En el enlace de Checkout que te envié, selecciona OXXO y sigue las indicaciones que aparecen ahí para completar el pago.'
      : 'En el Checkout seguro, selecciona OXXO y sigue las indicaciones que aparecen ahí para completar el pago.';
    parts.push(`No necesitas tarjeta para pagar con OXXO. ${checkoutReference}`);
  } else if (asksOxxo) {
    parts.push('Sí, aceptamos pagos en OXXO.');
  }

  const recognizedCount = [
    asksPrice, asksRenewal, unsupportedFeature, asksHowItWorks, asksStart,
    asksPortal, asksOxxo, noCard, businessLocation, asksPayment,
  ].filter(Boolean).length;
  if (!noCard && !unsupportedFeature && recognizedCount < 2 && !(asksOxxo && asksOxxoHow)) {
    return null;
  }

  return {
    response: [...new Set(parts)].join(' '),
    allow_purchase_cta: !checkoutAlreadySent && (
      !unsupportedFeature || asksPrice || asksRenewal || asksOxxo ||
      asksHowItWorks || asksStart || asksPortal
    ),
  };
}

function isInitialGenericInquiry(message) {
  const value = normalizeMessage(message);
  return /^(hola\s*)?(quiero|quisiera|me gustaria)?\s*(mas\s+)?informacion$/.test(value) ||
    /^(hola|buenos dias|buenas tardes|buenas noches)$/.test(value);
}

function isSubstantiveEngagement(message, interpretation) {
  if (interpretation?.buyer_signal === 'broad_information_request') return true;
  if (isInitialGenericInquiry(message)) return false;
  if (interpretation?.substantive_engagement === false) return false;
  return !['gratitude', 'ambiguous_acknowledgement', 'other'].includes(
    interpretation?.buyer_signal,
  );
}

function validContext(session, now) {
  const askedAt = Date.parse(session?.last_question_at || '');
  const expiresAt = Date.parse(session?.commercial_context_expires_at || '');
  const current = new Date(now).getTime();
  return session?.last_question_type === 'purchase_confirmation' &&
    session?.offer_version === OFFER_VERSION &&
    Number.isFinite(askedAt) &&
    Number.isFinite(expiresAt) &&
    current < expiresAt;
}

function validatedReminderTime(interpretation, now) {
  if (interpretation?.explicit_reminder_request !== true) return null;
  const scheduled = Date.parse(interpretation?.timing_iso || '');
  const current = new Date(now).getTime();
  if (!Number.isFinite(scheduled)) return null;
  const delta = scheduled - current;
  if (delta < 15 * 60 * 1000 || delta > 35 * 24 * 60 * 60 * 1000) return null;
  return new Date(scheduled).toISOString();
}

function topicEvent(topic) {
  if (topic === 'price') return 'price_question';
  if (topic === 'payment_methods') return 'payment_method_question';
  if (topic === 'health_scope' || topic === 'allergies') return 'health_question';
  return null;
}

function decideSalesTurn({ message, interpretation, session = {}, now = new Date() }) {
  const safeInterpretation = interpretation && interpretation.interpretation_valid !== false
    ? interpretation
    : { buyer_signal: 'other', topic: null, interpretation_valid: false };
  const currentTask = currentConversationalTask(message, safeInterpretation);
  const factualMessage = taskProductMessage(message, currentTask);
  const rawCurrentQuestionTopics = explicitProductQuestions(factualMessage);
  const resolvedCommercialQuestions = resolveCurrentCommercialQuestions(message, session);
  const continuationResponse = asksPost28DayContinuation(message) && !rawCurrentQuestionTopics.includes('fulfillment_timing') ? POST_28_DAY_RESPONSE : '';
  const unknownCurrentQuestion = currentQuestionDetails(factualMessage, MULTI_TOPIC_ANSWERS, resolvedCommercialQuestions?.response || continuationResponse || (asksPreparedFoodDelivery(message) ? PREPARED_FOOD_DELIVERY_RESPONSE : '')).some(d => d.uncertain);
  const practicalGuidance = currentQuestionDetails(factualMessage, MULTI_TOPIC_ANSWERS).some(d => d.practical);
  // The broad unknown-capability detector sees the grammatical "¿puedo...?".
  // Once the clause has been established as ordinary food-use guidance, that
  // generic marker is not a product topic.
  const currentQuestionTopics = practicalGuidance
    ? rawCurrentQuestionTopics.filter(topic => topic !== 'unconfirmed_detail')
    : rawCurrentQuestionTopics;
  // Preserve the established generic opening only before commercial context.
  const initialBroadInquiry = session.conversation_stage === 'new' &&
    !session.last_question_type && safeInterpretation.buyer_signal === 'broad_information_request' &&
    currentQuestionTopics.length === 1 && currentQuestionTopics[0] === 'how_it_works';
